 // Durable account-scoped rolling fixture: concurrent tabs, replay, abort and F5.
 {const ctx=await browser.newContext();const p=await ctx.newPage(),q=await ctx.newPage();await Promise.all([p.goto(url+'?bankpersistlab=1'),q.goto(url+'?bankpersistlab=1')]);await Promise.all([p.waitForFunction(()=>window.bankPersistFixture),q.waitForFunction(()=>window.bankPersistFixture)]);
 const account='123456789',at='2026-11-24T15:20:00+07:00',later='2026-11-25T08:00:00+07:00',b={id:'b',account,amount:'400000.8',quality:'clear',date:'24/11/2026',time:'15:16',memo:'KH MAU DON HANG'},k={...b,id:'k',verified:true,ownTransfer:false,direction:'credit',receivedAt:later};
 const ev=(record,type,time)=>({id:record.id,type:'evidence',event:{id:record.id,type,record,at:time,revision:type==='bill'?1:undefined}}),m={id:'m',type:'manual-receipt',billId:'b',amount:b.amount,operator:'fixture',reason:'fixture',at},a={receiptId:'m',customerId:'A'},cmd={entries:[ev(b,'bill',at),m]};
 const run=(page,command,abort=false)=>page.evaluate(async ({command,abort})=>{const J=window.bankPersistFixture,db=await J.openPersistent();try{return await J.changePersistent(db,'123456789',command,{abort})}finally{db.close()}},{command,abort});
 const read=page=>page.evaluate(async()=>{const J=window.bankPersistFixture,db=await J.openPersistent();try{return await J.readPersistent(db,'123456789')}finally{db.close()}});
 await assert.rejects(run(p,{...cmd,assignments:[a]},true));assert.equal((await read(q)).receiptCount,0);
 await run(p,cmd);const raced=await Promise.allSettled([run(p,{assignments:[a]}),run(q,{assignments:[{...a,customerId:'B'}]})]);assert.equal(raced.filter(x=>x.status==='fulfilled').length,1);const first=await read(p),winner=first.owners[0].customerId;assert.equal(first.assignedCount,1);
 await run(q,{...cmd,assignments:[{...a,customerId:winner}]});await p.reload();await p.waitForFunction(()=>window.bankPersistFixture);assert.equal((await read(p)).owners[0].customerId,winner);
 await run(q,{entries:[ev(k,'bank',later),{id:'link',type:'manual-link',billId:'b',bankId:'k',receiptId:'m',at:later}]});await p.close();const reopened=await ctx.newPage();await reopened.goto(url+'?bankpersistlab=1');await reopened.waitForFunction(()=>window.bankPersistFixture);const final=await read(reopened);assert.equal(final.receiptCount,1);assert.equal(final.assignedCount,1);assert.equal(final.receipts[0].bankId,'k');assert.equal(final.receipts[0].postedAt,'2026-11-24T08:20:00.000Z');assert.equal(final.receipts[0].amount,'400000.8');assert.equal(final.owners[0].customerId,winner);assert.equal(final.canPost,false);await ctx.close()}

