 const ctx=await browser.newContext({viewport:{width:390,height:844}}),a=await ctx.newPage(),b=await ctx.newPage();
 const open=async p=>{await p.goto(url+'?durablealertlab=1');await p.locator('.contact[data-id=nv]').evaluate(e=>e.click());await p.locator('.conversation .panel-head button[data-go=crm]').evaluate(e=>e.click());await p.locator('[data-durable-alert-status][data-ready=true]').waitFor()};
 const press=(p,name)=>p.getByRole('button',{name,exact:true}).evaluate(e=>e.click()),wait=(p,state,owned)=>p.waitForFunction(([state,owned])=>{const e=document.querySelector('[data-durable-alert-status]');return e?.dataset.state===state&&e.dataset.owned===String(owned)},[state,owned]);
 await open(a);await open(b);await Promise.all([press(a,'Nhận tín hiệu mẫu'),press(b,'Nhận tín hiệu mẫu')]);await Promise.all([a.waitForFunction(()=>document.querySelector('[data-durable-alert-status]')?.dataset.state==='offered'),b.waitForFunction(()=>document.querySelector('[data-durable-alert-status]')?.dataset.state==='offered')]);const owns=async p=>(await p.locator('[data-durable-alert-status]').getAttribute('data-owned'))==='true';assert.notEqual(await owns(a),await owns(b));const winner=await owns(a)?a:b,loser=winner===a?b:a;await press(winner,'Xác nhận qua cổng mẫu');await wait(winner,'accepted',false);await open(loser);await wait(loser,'accepted',false);await press(loser,'Nhận tín hiệu mẫu');await wait(loser,'accepted',false);
 await press(loser,'Tin mẫu tiếp theo');await wait(loser,'empty',false);await press(loser,'Nhận tín hiệu mẫu');await wait(loser,'offered',true);await press(loser,'Xác nhận chưa hiển thị');await wait(loser,'fallback',false);await press(loser,'Nhận tín hiệu mẫu');await wait(loser,'offered',true);assert.equal(await loser.locator('[data-durable-alert-status]').getAttribute('data-surface'),'push');await press(loser,'Phản hồi sai token');await wait(loser,'review',false);
 await press(loser,'Tin mẫu tiếp theo');await wait(loser,'empty',false);await press(loser,'Nhận tín hiệu mẫu');await wait(loser,'offered',true);await press(loser,'Hết thời hạn khóa');await wait(loser,'review',false);await ctx.close();console.log('DurableAlert atomic two-tab claim, reload, fallback, wrong token and expiry passed');
