 await dv.evaluate(el=>el.scrollTop-=80);await dyn.waitForTimeout(100);const away=await snapDyn();assert(away.bottom>2);await dv.evaluate(el=>{el.querySelector('[data-virtual-key="d1000"] [data-dynamic-extra]').hidden=false});await dyn.waitForFunction(total=>document.querySelector('[data-virtual-viewport]').scrollHeight>total,away.total);await dyn.waitForTimeout(100);const awayAfter=await snapDyn();assert.equal(awayAfter.key,away.key);assert(Math.abs(awayAfter.offset-away.offset)<=2);assert(awayAfter.bottom>2);
 await dyn.getByRole('button',{name:'Giữa mẫu',exact:true}).evaluate(e=>e.click());await dyn.waitForTimeout(200);const reading=await snapDyn();
 const marked=await dv.locator('[data-virtual-key="'+reading.key+'"]').elementHandle();
 await dyn.getByRole('button',{name:'Tải 20 dòng cũ',exact:true}).evaluate(e=>e.click());await dyn.waitForFunction(()=>document.querySelector('[data-virtual-viewport]').dataset.virtualCount==='1020');await dyn.waitForTimeout(200);const history=await snapDyn();assert.equal(history.key,reading.key);assert(Math.abs(history.offset-reading.offset)<=2,JSON.stringify({reading,history}));assert.equal(history.first,reading.first+20);assert(await marked.evaluate(e=>e.isConnected));
 await dyn.getByRole('button',{name:'Nhận 3 dòng mới',exact:true}).evaluate(e=>e.click());await dyn.waitForFunction(()=>document.querySelector('[data-virtual-viewport]').dataset.virtualCount==='1023');await dyn.waitForTimeout(150);const newWhileReading=await snapDyn();assert.equal(newWhileReading.key,history.key);assert(Math.abs(newWhileReading.offset-history.offset)<=2);assert(newWhileReading.bottom>2);assert(await marked.evaluate(e=>e.isConnected));await marked.dispose();
